#!/usr/bin/env bash
# Render DATA_ROOT/sirius.yaml from config.env knobs.
set -euo pipefail
# shellcheck source=lib.sh
source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/lib.sh"
load_config
ensure_dirs

GPU_USAGE_LINE="usage_limit_fraction: ${GPU_USAGE_LIMIT_FRACTION:-0.9}"
if [[ -n "${GPU_USAGE_LIMIT:-}" ]]; then
  GPU_USAGE_LINE="usage_limit_bytes: ${GPU_USAGE_LIMIT}"
fi

cat > "$YAML_PATH" <<EOF
# Generated by scripts/render-sirius-yaml.sh — do not edit by hand.
# Source knobs: ${BENCH_CONFIG_PATH:-$BENCH_ROOT/config.env}
sirius:
  topology:
    num_gpus: ${NUM_GPUS:-1}
  memory:
    gpu:
      ${GPU_USAGE_LINE}
      reservation_limit_fraction: ${GPU_RESERVATION_LIMIT_FRACTION:-1.0}
      downgrade_trigger_fraction: ${GPU_DOWNGRADE_TRIGGER_FRACTION:-0.8}
      downgrade_stop_fraction: ${GPU_DOWNGRADE_STOP_FRACTION:-0.6}
    host:
      capacity_bytes: ${HOST_CAPACITY}
      reservation_limit_fraction: ${HOST_RESERVATION_LIMIT_FRACTION:-1.0}
      downgrade_trigger_fraction: ${HOST_DOWNGRADE_TRIGGER_FRACTION:-0.9}
      downgrade_stop_fraction: ${HOST_DOWNGRADE_STOP_FRACTION:-0.8}
      block_size: ${HOST_BLOCK_SIZE:-1MiB}
      pool_size: ${HOST_POOL_SIZE:-128}
      initial_number_pools: ${HOST_INITIAL_NUMBER_POOLS:-4}
    disk:
      disk_id: ${DISK_ID:-0}
      capacity_bytes: ${DISK_CAPACITY}
      downgrade_root_dirs: ${SPILL_DIR}
  executor:
    pipeline:
      num_threads: ${PIPELINE_THREADS:-4}
    downgrade:
      num_threads: ${DOWNGRADE_THREADS:-1}
    task_creator:
      num_threads: ${TASK_CREATOR_THREADS:-2}
  operator_params:
    scan_task_batch_size: ${SCAN_TASK_BATCH_SIZE:-768MiB}
    max_sort_partition_bytes: ${MAX_SORT_PARTITION_BYTES:-0}
    hash_partition_bytes: ${HASH_PARTITION_BYTES:-768MiB}
    concat_batch_bytes: ${CONCAT_BATCH_BYTES:-768MiB}
    max_build_hash_table_bytes: ${MAX_BUILD_HASH_TABLE_BYTES:-768MiB}
  telemetry:
    enable_quent: true
    enable_batch_events: true
    exporter: ${QUENT_EXPORTER}
    output_directory: ${TELEMETRY_DIR}
    engine_name: ${ENGINE_NAME}
EOF

log "wrote $YAML_PATH (host=${HOST_CAPACITY} disk=${SPILL_DIR})"
cat "$YAML_PATH"
